(function(){"use strict";var stats=null;function count(n,one,many){return Number(n).toLocaleString("en")+" "+(Number(n)===1?one:many)}function drawStats(){var el=document.getElementById("welcome-stats");if(!el)return;if(!stats||!(stats.stores>0)){el.textContent="";el.classList.remove("is-ready");return}var parts=[count(stats.stores,"store","stores")];if(stats.products>0)parts.push(count(stats.products,"product","products"));el.textContent=parts.join(" · ");el.classList.add("is-ready")}function loadStats(){if(typeof Api==="undefined")return;var kept=Api.recall("siteStats");if(kept){stats=kept;drawStats()}var call;try{call=Api.get("siteStats")}catch(e){return}call.then(function(res){if(!res||!res.ok||typeof res.stores!=="number")return;stats={stores:res.stores,products:Number(res.products)||0};Api.remember("siteStats",stats);drawStats()}).catch(function(){})}function init(){try{localStorage.removeItem("mwk_lang")}catch(e){}if(document.documentElement.classList.contains("welcome-on"))loadStats()}if(document.readyState==="complete")init();else document.addEventListener("DOMContentLoaded",init)})();